private_reproducibility.exact_probe_source:
import { strict as assert } from "node:assert";
import { Database } from "bun:sqlite";
import { SQL } from "bun";
import { mkdtempSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
const base = "/private/tmp/rm306-selection-correction.DuxBaD";
const renamed = Bun.env.REVIEW_RENAMED === "1";
const folder = join(base, renamed ? "renamed" : "generated");
const database = Bun.env.REVIEW_DATABASE_URL;
delete Bun.env.DATABASE_URL; delete Bun.env.SQLITE_PATH;
if (database) {
  const u = new URL(database);
  assert.equal(u.hostname, "127.0.0.1"); assert.match(u.pathname, /^\/jadpo_auth_test_selection_[a-z_]+$/);
  Bun.env.DATABASE_URL = database;
} else Bun.env.SQLITE_PATH = join(mkdtempSync(join(base,"sqlite-probe-")), "application.sqlite");
const app = await import(pathToFileURL(join(folder,"app.ts")).href);
const { persistence } = await import(pathToFileURL(join(folder,"persistence.ts")).href);
const db = database ? null : new Database(Bun.env.SQLITE_PATH);
const sql = database ? new SQL(database, {max:5,prepare:false}) : null;
const rows = (s:string,v:any[]=[]) => sql ? sql.unsafe(s,v) : Promise.resolve(db!.prepare(s).all(...v));
const field = renamed ? "record_id" : "id", ownerField = renamed ? "recipient_key" : "owner_id";
const op = "2026-10-05T08:00:00.000Z", at = "2026-10-08T08:00:00.000Z";
const dueA = "2026-10-06T08:00:00.000Z", dueB = "2026-10-07T08:00:00.000Z";
const owner = crypto.randomUUID(), service = crypto.randomUUID(), member = crypto.randomUUID();
const time = (t:string|number) => sql ? new Date(t).toISOString() : new Date(t).getTime();
await rows(`INSERT INTO "user" (${field},authentication_subject,email,status,created_at,disabled_at) VALUES ($1,$1,$2,'active',$3,NULL)`,[owner,`${owner}@example.invalid`,time(op)]);
await rows(`INSERT INTO service (${field},owner_id,name,status,created_at,disabled_at) VALUES ($1,$2,$3,'active',$4,NULL)`,[service,owner,`review-${service}`,time(op)]);
await rows(`INSERT INTO reminder_service_membership (${field},service_id,role) VALUES ($1,$2,'sender')`,[member,service]);
const env = {DATABASE_URL:"https://db.example.invalid/review",SESSION_SIGNING_KEY:Buffer.alloc(32,71).toString("base64url"),BROWSER_ORIGIN:"https://todo.example.invalid",OIDC_ISSUER:"https://issuer.example.invalid",OIDC_AUDIENCE:"todo",MAIL_API_KEY:Buffer.alloc(32,72).toString("base64url"),MAIL_SENDER:"review@example.invalid"};
await app.initializeApplication(env);
const host = app.authenticationHost(), now = Date.now();
const issued = await host.issueServiceCredential("api_bearer",`review-${service}`,now+3600000,now);
const proof = await host.prepareDeliveryCredential("api_bearer",issued.credential,now);
const binding = JSON.parse(readFileSync(join(folder,"binding.json"),"utf8"));
assert.equal(binding.execution_profile,null); assert.equal(binding.runtime_lowering_supported,false);
const client = persistence.withOperationTime(op).withPolicy({kind:"user",subject:owner,values:{user_id:owner}},"Todo.patch_todo");
const worker = persistence.withOperationTime(at);
const scan = (after:any=null) => worker.transaction((tx:any)=>tx.select_delivery_intents(binding.binding,proof,after));
const patchMethod = `update_required_Todo_by_${field}_patch_title_and_status_and_due_at_set_reminder_sent_at`;
const todo = (id=crypto.randomUUID()) => ({[field]:id,[ownerField]:owner,title:"independent",status:"open",due_at:dueA,reminder_sent_at:null,created_at:op,updated_at:op,deleted_at:null});
const clear = () => rows('DELETE FROM todo');
const violations:string[]=[];
await client.create_Todo(todo());
const page = await scan(), original = page.intents[0];
assert.equal(page.intents.length,1); assert.equal(original.sourceRevision,"1");
assert.equal(original.payload.idempotency_key,original.intentId); assert.equal(original.payload.due_at,dueA);
assert.equal(Object.hasOwn(persistence,"enqueueIntent"),false);
await assert.rejects(worker.transaction((tx:any)=>tx.select_delivery_intents(binding.binding,{})),(e:any)=>e.code==="invalid_credentials");
original.payload.todo_title="detached";
assert.equal((await scan()).intents[0].payload.todo_title,"independent");
console.log(`PASS ${renamed?"RENAMED":"BASE"} exact ownerFK/identity/native host/payload/guard control`);

await clear();
const faulted = todo(); await client.create_Todo(faulted);
if (sql) await rows('ALTER TABLE "__jadpo_delivery_schedules_v1" RENAME COLUMN schedule_revision TO invalid_revision');
else {
  // SQLite accepts an unknown double-quoted column as a string literal. Use an
  // actual unresolved native VIEW dependency instead of that false injection.
  await rows('ALTER TABLE "__jadpo_delivery_schedules_v1" RENAME TO "__review_schedule_backup"');
  await rows('CREATE VIEW "__jadpo_delivery_schedules_v1" AS SELECT * FROM "__review_absent_schedule_relation"');
}
try {
  await worker.withPolicy({kind:"user",subject:owner,values:{user_id:owner}},"Todo.patch_todo").transaction(async(tx:any)=>{
    await assert.rejects(tx.select_delivery_intents(binding.binding,proof),(e:any)=>["delivery.schedule.read","delivery.schedule.schema"].includes(e.operation));
    await tx[`update_required_Todo_by_${field}_set_title`](faulted[field],"surrounding commit");
  });
} finally {
  if(sql) await rows('ALTER TABLE "__jadpo_delivery_schedules_v1" RENAME COLUMN invalid_revision TO schedule_revision');
  else {await rows('DROP VIEW "__jadpo_delivery_schedules_v1"');await rows('ALTER TABLE "__review_schedule_backup" RENAME TO "__jadpo_delivery_schedules_v1"');}
}
assert.equal((await rows(`SELECT title FROM todo WHERE ${field}=$1`,[faulted[field]]))[0].title,"surrounding commit");
assert.equal(Number((await rows('SELECT COUNT(*) AS n FROM "__jadpo_deliveries_v1" WHERE source_entity_id=$1',[faulted[field]]))[0].n),0);
console.log('PASS genuine caught native revision-read SQL fault: no page enrollment; surrounding source mutation commits');

const generic = {job:"review_generic",sourceOperation:"review",sourceEntity:"review",sourceEntityId:crypto.randomUUID(),sourceRevision:"1",orderingKey:crypto.randomUUID(),payloadVersion:"review.v1",payload:{a:1}};
const g = await client.transaction((tx:any)=>tx.enqueue_delivery_intent(generic));
assert.equal((await client.transaction((tx:any)=>tx.enqueue_delivery_intent(generic))).intentId,g.intentId);
await assert.rejects(client.transaction((tx:any)=>tx.enqueue_delivery_intent({...generic,payload:{a:2}})),(e:any)=>e.operation==="delivery.identity_conflict");
console.log('PASS generic enqueue strict same-caller canonical payload equality retained');

if (sql && !renamed) {
  const wait = async() => {
    for(let n=0;n<400;n++) {
      const result = await sql.unsafe("SELECT COUNT(*)::int AS n FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE 'SELECT%AS source_id%'");
      if(result[0].n>0) return;
      await Bun.sleep(10);
    }
    throw new Error('No observable source-selection lock wait within4s');
  };
  const race = async(id:string,change:any={due_at:dueB}) => {
    let ready!:()=>void, release!:()=>void;
    const patched = new Promise<void>(r=>ready=r), held = new Promise<void>(r=>release=r);
    const writer = client.transaction(async(tx:any)=>{await tx[patchMethod](id,change,null);ready();await held;});
    await patched;
    // Capture rejection as data; do not let a matcher wait before releasing writer.
    const reading=scan().then(page=>({page,error:null}),error=>({page:null,error}));
    try {await wait();} finally {release();}
    await writer;
    return reading;
  };
  await clear(); const single=todo(); await client.create_Todo(single);
  const raced = await race(single.id);
  assert.equal(raced.page,null); assert.equal(raced.error.operation,"delivery.selection_changed");
  assert.equal(Number((await rows('SELECT COUNT(*) AS n FROM "__jadpo_deliveries_v1" WHERE source_entity_id=$1',[single.id]))[0].n),0);
  const freshSingle=(await scan()).intents[0];
  assert.equal(freshSingle.sourceRevision,"2");assert.equal(freshSingle.payload.due_at,dueB);
  console.log('PASS observed PostgreSQL single-row changed capture refuses before enrollment; fresh scan reads post-lock revision2/current due');

  for (const [iteration,change] of [{due_at:dueB},{due_at:at},{status:"done"}].entries()) {
    await clear();
    const ids = Array.from({length:501},(_,i)=>`018f57d0-bf42-4f25-9417-${String(10001+iteration*1000+i).padStart(12,"0")}`);
    await client.transaction(async(tx:any)=>{for(const id of ids) await tx.create_Todo(todo(id));});
    const refused=await race(ids[499],change);
    assert.equal(refused.page,null);assert.equal(refused.error.operation,"delivery.selection_changed");
    const placeholders=ids.map((_,i)=>`$${i+1}`).join(",");
    assert.equal(Number((await rows(`SELECT COUNT(*) AS n FROM "__jadpo_deliveries_v1" WHERE source_entity_id IN (${placeholders})`,ids))[0].n),0);
    assert.equal(Number((await rows(`SELECT COUNT(*) AS n FROM "__jadpo_delivery_keys_v1" WHERE ordering_key IN (${placeholders})`,ids))[0].n),0);
    const first=await scan();
    const second=first.after===null?{intents:[],after:null}:await scan(first.after);
    const all=[...first.intents,...second.intents];
    const expected=change.due_at===dueB?ids:ids.filter(id=>id!==ids[499]);
    assert.equal(all.length,expected.length);assert.deepEqual(new Set(all.map((i:any)=>i.sourceEntityId)),new Set(expected));
    assert.equal(second.after,null);
    if (change.due_at===dueB) {
      const moved=all.find((i:any)=>i.sourceEntityId===ids[499]);
      assert.equal(moved.sourceRevision,"2");assert.equal(moved.payload.due_at,dueB);
    }
    console.log(JSON.stringify({correction:"SE-PAGE-LOCK-01",iteration,change,observed_lock:true,refusal:refused.error.operation,partial_intents:0,partial_keys:0,fresh_first:first.intents.length,fresh_second:second.intents.length,eligible_covered:expected.length}));
  }
}
if(sql) await sql.close(); if(db) db.close();
console.log(JSON.stringify({review_adapter:sql?"postgres":"sqlite",renamed,violations,complete:true}));
process.exit(violations.length?2:0);
